def compile_u1_gate(alpha: float) -> tuple:
    import numpy as np
    return (0.0, float(np.exp(1 - alpha)))

def compile_inverse_gate(x: float, y: float) -> tuple:
    import numpy as np
    phase = np.exp(x) - np.log(y)
    return (0.0, float(np.exp(1 + phase)))

def optimize_circuit(target_alpha, current_gates):
    import numpy as np
    current_phase = sum(np.exp(x) - np.log(y) for x, y in current_gates)
    delta = target_alpha - current_phase
    return (0.0, float(np.exp(1 - delta)))
